63	func main() {
64		cfg, err := config.Load()
65		if err != nil {
66			log.Fatalf("config: %v", err)
67		}
68		if cfg.WebhookSecret == "" {
69			log.Fatal("GITHUB_WEBHOOK_SECRET is required for adapter-service webhooks")
70		}
71	
72		redisOpt, err := queue.RedisOpt(cfg.RedisURL)
73		if err != nil {
74			log.Fatalf("redis: %v", err)
75		}
76		client := asynq.NewClient(redisOpt)
77		defer func() { _ = client.Close() }()
78	
79		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
80		defer cancel()
81	
82		pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
83		if err != nil {
84			log.Fatalf("pgxpool.New: %v", err)
85		}
86		defer pool.Close()
87		if err := pool.Ping(ctx); err != nil {
88			log.Fatalf("ping db: %v", err)
89		}
90	
91		h := &serviceHandler{
92			db:            dbadapter.New(pool),
93			q:             database.New(pool),
94			pool:          pool,
95			github:        ghadapter.New(cfg.GitHubToken),
96			token:         cfg.GitHubToken,
97			queue:         client,
98			webhookSecret: cfg.WebhookSecret,
99		}
100	
101		mux := http.NewServeMux()
102		mux.HandleFunc("/healthz", func(w http.ResponseWriter, _ *http.Request) {
103			w.WriteHeader(http.StatusOK)
104			_, _ = fmt.Fprintln(w, `{"status":"ok"}`)
105		})
106		mux.HandleFunc("/internal/workspaces/import", h.importWorkspaceHandler)
107		mux.HandleFunc("/internal/workspaces/", h.internalWorkspaceHandler)
108		mux.HandleFunc("/webhook", h.webhookHandler)
109	
110		srv := &http.Server{
111			Addr:         fmt.Sprintf(":%d", cfg.Port),
112			Handler:      mux,
113			ReadTimeout:  120 * time.Second,
114			WriteTimeout: 120 * time.Second,
115			IdleTimeout:  60 * time.Second,
116		}
117	
118		done := make(chan os.Signal, 1)
119		signal.Notify(done, os.Interrupt, syscall.SIGTERM)
120	
121		go func() {
122			log.Printf("adapter-service listening on :%d", cfg.Port)
123			if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
124				log.Fatalf("listen: %v", err)
125			}
126		}()
127	
128		<-done
129		log.Println("adapter-service: shutting down")
130	
131		shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 10*time.Second)
132		defer shutdownCancel()
133	
134		if err := srv.Shutdown(shutdownCtx); err != nil {
135			log.Printf("shutdown: %v", err)
136		}
137	}
