139	func (h *serviceHandler) importWorkspaceHandler(w http.ResponseWriter, r *http.Request) {
140		if r.Method != http.MethodPost {
141			w.Header().Set("Allow", http.MethodPost)
142			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
143			return
144		}
145	
146		defer func() { _ = r.Body.Close() }()
147		var req importWorkspaceRequest
148		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
149			writeSourceError(w, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid JSON body: "+err.Error()))
150			return
151		}
152		if strings.TrimSpace(req.RepoURL) == "" {
153			writeSourceError(w, domain.NewValidationError(domain.ErrValidationMissingInput, "repo_url is required"))
154			return
155		}
156		if req.DefaultBranch == "" {
157			req.DefaultBranch = "main"
158		}
159	
160		owner, repo, err := parseGitHubRepo(req.RepoURL)
161		if err != nil {
162			writeAnyError(w, err)
163			return
164		}
165		if existing, found, err := h.findExistingImport(r.Context(), owner, repo); err != nil {
166			writeAnyError(w, err)
167			return
168		} else if found {
169			writeExistingImport(w, existing, req.RepoURL, req.DefaultBranch)
170			return
171		}
172	
173		// Validate the GitHub source and read workspace metadata so the HTTP request
174		// can return quickly while full reconciliation runs in the background worker.
175		snap, err := h.github.FetchWorkspaceMetadata(r.Context(), domain.ImportInput{
176			RepoURL:       req.RepoURL,
177			DefaultBranch: req.DefaultBranch,
178			Token:         h.token,
179		})
180		if err != nil {
181			writeAnyError(w, err)
182			return
183		}
184	
185		workspaceID := uuid.NewString()
186		name := strings.TrimSpace(req.Name)
187		if name == "" {
188			name = snap.Name
189		}
190		if name == "" {
191			name = owner + "/" + repo
192		}
193		slug := slugify(name)
194		if slug == "" {
195			slug = workspaceID
196		}
197	
198		workspaceID, err = h.createImportPlaceholder(r.Context(), workspaceID, name, slug, req.RepoURL, req.DefaultBranch, snap.ManagementRepoID)
199		if err != nil {
200			// Only attempt the duplicate-detection fallback for unique constraint violations.
201			// For infrastructure errors (connection failure, timeout) we return immediately
202			// so they are not masked by a second failing query.
203			if !isUniqueViolation(err) {
204				writeAnyError(w, err)
205				return
206			}
207			if existing, found, findErr := h.findExistingImport(r.Context(), owner, repo); findErr != nil {
208				writeAnyError(w, findErr)
209				return
210			} else if found {
211				writeExistingImport(w, existing, req.RepoURL, req.DefaultBranch)
212				return
213			}
214			if isUniqueConstraintViolation(err, "workspaces_slug_unique") {
215				writeSourceError(w, domain.NewDatabaseConflictError(fmt.Sprintf("workspace slug %q already exists for another GitHub repository", slug)))
216				return
217			}
218			writeAnyError(w, err)
219			return
220		}
221		run, err := h.insertRunningRun(r.Context(), workspaceID, "api_import", "full", req.DefaultBranch)
222		if err != nil {
223			writeAnyError(w, err)
224			return
225		}
226		syncRunID := uuidString(run.ID)
227	
228		payload := queue.WorkspaceSyncPayload{
229			WorkspaceID:   workspaceID,
230			RepoURL:       req.RepoURL,
231			DefaultBranch: req.DefaultBranch,
232			Trigger:       "api_import",
233			Mode:          "full",
234			Name:          name,
235			SyncRunID:     syncRunID,
236		}
237		task, err := queue.NewWorkspaceSyncTask(payload)
238		if err != nil {
239			writeAnyError(w, err)
240			return
241		}
242		info, err := h.queue.Enqueue(task, asynq.TaskID(workspaceSyncTaskID(payload)))
243		if err != nil {
244			if failErr := h.markRunFailed(r.Context(), run.ID, "ENQUEUE_FAILED", err.Error()); failErr != nil {
245				log.Printf("mark import enqueue failed run failed workspace_id=%s run_id=%s: %v", workspaceID, syncRunID, failErr)
246			}
247			if isDedupeError(err) {
248				writeJSON(w, http.StatusAccepted, map[string]string{
249					"status":       "already_queued",
250					"workspace_id": workspaceID,
251					"sync_run_id":  syncRunID,
252					"type":         queue.TypeWorkspaceSync,
253				})
254				return
255			}
256			writeAnyError(w, fmt.Errorf("enqueue task: %w", err))
257			return
258		}
259	
260		writeJSON(w, http.StatusAccepted, map[string]string{
261			"workspace_id":   workspaceID,
262			"name":           name,
263			"slug":           slug,
264			"repo_url":       req.RepoURL,
265			"default_branch": req.DefaultBranch,
266			"sync_run_id":    syncRunID,
267			"task_id":        info.ID,
268			"queue":          info.Queue,
269			"type":           info.Type,
270		})
271	}
