273	func (h *serviceHandler) internalWorkspaceHandler(w http.ResponseWriter, r *http.Request) {
274		if r.Method != http.MethodPost {
275			w.Header().Set("Allow", http.MethodPost)
276			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
277			return
278		}
279	
280		workspaceID, ok := workspaceIDFromSyncPath(r.URL.Path)
281		if !ok {
282			http.NotFound(w, r)
283			return
284		}
285	
286		uid, err := pgUUID(workspaceID)
287		if err != nil {
288			writeAnyError(w, err)
289			return
290		}
291		src, err := h.q.GetGitHubSource(r.Context(), uid)
292		if err != nil {
293			if errors.Is(err, pgx.ErrNoRows) {
294				writeSourceError(w, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "github source not found for workspace"))
295				return
296			}
297			writeAnyError(w, err)
298			return
299		}
300	
301		defaultBranch := "main"
302		if src.DefaultBranch != nil && *src.DefaultBranch != "" {
303			defaultBranch = *src.DefaultBranch
304		}
305		payload := queue.WorkspaceSyncPayload{
306			WorkspaceID:   workspaceID,
307			RepoURL:       src.RepoURL,
308			DefaultBranch: defaultBranch,
309			Trigger:       "api_sync",
310			Mode:          "full",
311		}
312		task, err := queue.NewWorkspaceSyncTask(payload)
313		if err != nil {
314			writeAnyError(w, err)
315			return
316		}
317		info, err := h.queue.Enqueue(task, asynq.TaskID(workspaceSyncTaskID(payload)))
318		if err != nil {
319			if isDedupeError(err) {
320				writeJSON(w, http.StatusAccepted, map[string]string{
321					"status": "already_queued",
322					"type":   queue.TypeWorkspaceSync,
323				})
324				return
325			}
326			writeAnyError(w, fmt.Errorf("enqueue task: %w", err))
327			return
328		}
329	
330		writeJSON(w, http.StatusAccepted, map[string]string{
331			"task_id": info.ID,
332			"queue":   info.Queue,
333			"type":    info.Type,
334		})
335	}
