func (h *Handler) ensureSyncRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode, branch string, commitSHA *string, requireRefs bool) (pgtype.UUID, error) {
	if payload.SyncRunID != "" {
