27	// buildSig computes the HMAC-SHA256 signature for a payload.
28	func buildSig(secret string, body []byte) string { //nolint:unparam
29		mac := hmac.New(sha256.New, []byte(secret))
30		mac.Write(body)
31		return "sha256=" + hex.EncodeToString(mac.Sum(nil))
32	}
33	
34	// TestWebhookHandler_InvalidSignature verifies that requests with wrong HMAC are rejected.
35	func TestWebhookHandler_InvalidSignature(t *testing.T) {
36		h := &serviceHandler{webhookSecret: "mysecret"}
37	
38		body := []byte(`{"ref":"refs/heads/main","repository":{"clone_url":"https://github.com/o/r"},"commits":[]}`)
39		req := httptest.NewRequest(http.MethodPost, "/webhook", strings.NewReader(string(body)))
40		req.Header.Set("X-GitHub-Event", "push")
41		req.Header.Set("X-Hub-Signature-256", "sha256=badsignature")
42		rec := httptest.NewRecorder()
43	
44		h.webhookHandler(rec, req)
45		if rec.Code != http.StatusUnauthorized {
46			t.Errorf("expected 401, got %d", rec.Code)
47		}
48	}
49	
50	// TestWebhookHandler_MethodNotAllowed verifies that non-POST requests are rejected.
51	func TestWebhookHandler_MethodNotAllowed(t *testing.T) {
52		h := &serviceHandler{}
53		req := httptest.NewRequest(http.MethodGet, "/webhook", nil)
54		rec := httptest.NewRecorder()
55		h.webhookHandler(rec, req)
56		if rec.Code != http.StatusMethodNotAllowed {
