523	func (e *recordingEnqueuer) Enqueue(task *asynq.Task, _ ...asynq.Option) (*asynq.TaskInfo, error) {
524		if e.err != nil {
525			return nil, e.err
526		}
527		switch task.Type() {
528		case queue.TypeWorkspaceSync:
529			var payload queue.WorkspaceSyncPayload
530			if err := json.Unmarshal(task.Payload(), &payload); err != nil {
531				return nil, err
532			}
533			e.workspaceSyncs = append(e.workspaceSyncs, payload)
534		case queue.TypeTaskSync:
535			var payload queue.TaskSyncPayload
536			if err := json.Unmarshal(task.Payload(), &payload); err != nil {
537				return nil, err
538			}
539			e.taskSyncs = append(e.taskSyncs, payload)
540		}
541		return &asynq.TaskInfo{ID: "task-id", Queue: queue.QueueDefault, Type: task.Type()}, nil
542	}
