543		switch {
544		case strings.Contains(query, "FROM workspaces"):
545			return workspaceRow{workspaceID: f.workspaceID}
546		case strings.Contains(query, "FROM workspace_features"):
547			return errorRow{err: pgx.ErrNoRows}
548		case strings.Contains(query, "INSERT INTO workspace_sync_runs"):
549			f.insertSyncRunCalls++
550			if len(args) > 5 {
551				if mode, ok := args[5].(string); ok {
552					f.lastMode = mode
553				}
554			}
555			return syncRunRow{
556				id:          f.runID,
557				workspaceID: f.workspaceID,
558				status:      "running",
559				mode:        f.lastMode,
560			}
561		case strings.Contains(query, "UPDATE workspace_sync_runs SET") && strings.Contains(query, "status        = 'failed'"):
562			f.updateFailedCalls++
563			if len(args) > 1 {
564				f.lastErrorCode, _ = args[1].(*string)
565			}
566			if len(args) > 2 {
567				f.lastErrorMessage, _ = args[2].(*string)
568			}
569			return syncRunRow{
