		}
	case strings.Contains(query, "UPDATE workspace_sync_runs SET") && strings.Contains(query, "status        = 'failed'"):
		f.updateFailedCalls++
		if len(args) > 1 {
			f.lastErrorCode, _ = args[1].(*string)
		}
		if len(args) > 2 {
			f.lastErrorMessage, _ = args[2].(*string)
		}
		return syncRunRow{
