		return syncRunRow{
			id:          f.runID,
			workspaceID: f.workspaceID,
			status:      "success",
			mode:        f.lastMode,
		}
	default:
		f.t.Fatalf("unexpected query: %s", query)
		return errorRow{err: errors.New("unexpected query")}
	}
