type workspaceRow struct {
	workspaceID pgtype.UUID
}

func (r workspaceRow) Scan(dest ...any) error {
	values := []any{
		r.workspaceID,
		"workspace",
		"Workspace",
		"management-repo",
		(*string)(nil),
		pgtype.Timestamptz{},
		pgtype.Timestamptz{},
	}
	return scanValues(dest, values)
}

type syncRunRow struct {
	id           pgtype.UUID
	workspaceID  pgtype.UUID
	status       string
	mode         string
	errorCode    *string
	errorMessage *string
}

func (r syncRunRow) Scan(dest ...any) error {
	changedPaths := json.RawMessage("[]")
	metadata := json.RawMessage("{}")
	values := []any{
		r.id,
		r.workspaceID,
		"redis_worker",
		(*string)(nil),
		pgtype.UUID{},
		pgtype.UUID{},
		r.mode,
		r.status,
		(*string)(nil),
		changedPaths,
		pgtype.Timestamptz{},
		pgtype.Timestamptz{},
		r.errorCode,
		r.errorMessage,
		metadata,
	}
	return scanValues(dest, values)
}

type errorRow struct {
	err error
}

func (r errorRow) Scan(...any) error {
	return r.err
}

func scanValues(dest []any, values []any) error {
	if len(dest) != len(values) {
		return errors.New("unexpected scan destination count")
	}
	for i, d := range dest {
		switch out := d.(type) {
		case *pgtype.UUID:
			*out = values[i].(pgtype.UUID) //nolint:errcheck
		case *string:
			*out = values[i].(string) //nolint:errcheck
		case **string:
			*out = values[i].(*string) //nolint:errcheck
		case *json.RawMessage:
			*out = values[i].(json.RawMessage) //nolint:errcheck
		case *pgtype.Timestamptz:
			*out = values[i].(pgtype.Timestamptz) //nolint:errcheck
		default:
			return errors.New("unsupported scan destination")
		}
	}
	return nil
}

func mustTestUUID(t *testing.T, raw string) pgtype.UUID {
	t.Helper()
	var uid pgtype.UUID
	if err := uid.Scan(raw); err != nil {
		t.Fatalf("scan uuid %s: %v", raw, err)
	}
	return uid
}

