		db:            dbadapter.New(pool),
		q:             database.New(pool),
		pool:          pool,
		github:        ghadapter.New(cfg.GitHub.Token),
		token:         cfg.GitHub.Token,
		queue:         client,
		webhookSecret: cfg.GitHub.WebhookSecret,
	}

